content:
:root {
  --background: #0d0f12;
  --surface: #12151a;
  --surface-raised: #171b21;
  --surface-hover: #1d222a;
  --border: #272d36;
  --border-subtle: #1e232b;
  --foreground: #ecedf0;
  --muted: #9299a5;
  --faint: #656d79;
  --accent: #c5ff55;
  --accent-muted: rgb(197 255 85 / 9%);
  --danger: #ff7676;
  --radius: 10px;
}

* {
  box-sizing: border-box;
  scrollbar-width: thin;
  scrollbar-color: #3b424e transparent;
}

*::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

*::-webkit-scrollbar-thumb {
  min-height: 34px;
  border: 2px solid transparent;
  border-radius: 999px;
  background: #3b424e;
  background-clip: padding-box;
}

*::-webkit-scrollbar-thumb:hover {
  background: #555e6c;
  background-clip: padding-box;
}

*::-webkit-scrollbar-corner {
  background: transparent;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  font-size: 14px;
}

button,
input {
  font: inherit;
}

button {
  color: inherit;
}

code,
kbd {
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
}

/* ============================================================
   APPLICATION SHELL
   ============================================================ */

.workbench {
  display: grid;
  grid-template-rows:
    28px
    34px
    48px
    minmax(0, 1fr)
    26px;
  height: 100vh;
  min-width: 900px;
  overflow: hidden;
}

/* ============================================================
   APPLICATION MENU BAR
   ============================================================ */

.application-menu-bar {
  position: relative;
  z-index: 60;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border-subtle);
  background: #0b0d10;
  padding: 0 8px;
  user-select: none;
}

.application-menus {
  position: relative;
  display: flex;
  align-items: center;
  height: 100%;
}

.application-menu-button {
  height: 22px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  padding: 0 8px;
  color: var(--muted);
  font-size: 11px;
  cursor: default;
}

.application-menu-button:hover,
.application-menu-button.active {
  background: var(--surface-hover);
  color: var(--foreground);
}

.application-title {
  padding-right: 5px;
  color: var(--faint);
  font-size: 10px;
}

.application-menu-dropdown {
  position: absolute;
  top: 27px;
  left: 0;
  z-index: 100;
  display: grid;
  min-width: 190px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface-raised);
  padding: 5px;
  box-shadow:
    0 12px 34px rgb(0 0 0 / 35%),
    0 2px 8px rgb(0 0 0 / 30%);
}

.application-menu-dropdown button {
  height: 30px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  padding: 0 9px;
  color: var(--muted);
  text-align: left;
  font-size: 11px;
  cursor: default;
}

.application-menu-dropdown button:hover:not(:disabled) {
  background: var(--surface-hover);
  color: var(--foreground);
}

.application-menu-dropdown button:disabled {
  color: var(--faint);
}

/* ============================================================
   TAB BAR
   ============================================================ */

.tab-bar {
  display: flex;
  align-items: stretch;
  border-bottom: 1px solid var(--border);
  background: #0e1115;
  user-select: none;
}

.tabs {
  display: flex;
  min-width: 0;
}

.workbench-tab {
  display: flex;
  gap: 7px;
  align-items: center;
  min-width: 130px;
  max-width: 220px;
  height: 100%;
  border: 0;
  border-right: 1px solid var(--border);
  background: transparent;
  padding: 0 12px;
  color: var(--muted);
  font-size: 10px;
  cursor: default;
}

.workbench-tab span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.workbench-tab.active {
  position: relative;
  background: var(--surface);
  color: var(--foreground);
}

.workbench-tab.active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 1px;
  background: var(--surface);
  content: "";
}

.new-tab-button {
  width: 34px;
  border: 0;
  border-right: 1px solid var(--border);
  background: transparent;
  color: var(--faint);
  cursor: default;
}

.new-tab-button:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

/* ============================================================
   CONTEXT / BREADCRUMB BAR
   ============================================================ */

.topbar {
  display: grid;
  grid-template-columns:
    240px
    minmax(0, 1fr)
    auto;
  align-items: center;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  padding-right: 12px;
}

.navigator-collapsed .topbar {
  grid-template-columns:
    52px
    minmax(0, 1fr)
    auto;
}

.brand {
  display: flex;
  gap: 10px;
  align-items: center;
  height: 100%;
  padding: 0 14px;
  border-right: 1px solid var(--border);
}

.navigator-collapsed .brand {
  justify-content: center;
  padding: 0;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface-raised);
  color: var(--accent);
  font-weight: 700;
}

.brand-text {
  display: flex;
  gap: 6px;
  align-items: baseline;
}

.navigator-collapsed .brand-text {
  display: none;
}

.brand-text strong {
  font-size: 14px;
}

.brand-text span {
  color: var(--muted);
  font-size: 12px;
}

.topbar-context {
  display: flex;
  gap: 7px;
  align-items: center;
  min-width: 0;
  padding: 0 18px;
  color: var(--muted);
  font-size: 12px;
}

.topbar-context strong {
  overflow: hidden;
  color: var(--foreground);
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-separator {
  color: var(--faint);
}

.command-button {
  display: flex;
  gap: 22px;
  align-items: center;
  height: 32px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface-raised);
  padding: 0 8px 0 11px;
  color: var(--muted);
  cursor: pointer;
}

.command-button:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.command-button kbd {
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--surface);
  padding: 2px 5px;
  color: var(--faint);
  font-size: 10px;
}

/* ============================================================
   MAIN WORKBENCH GRID
   ============================================================ */

.workbench-body {
  display: grid;
  grid-template-columns:
    240px
    minmax(0, 1fr)
    280px;
  min-height: 0;
}

.navigator-collapsed .workbench-body {
  grid-template-columns:
    52px
    minmax(0, 1fr)
    280px;
}

.inspector-collapsed .workbench-body {
  grid-template-columns:
    240px
    minmax(0, 1fr)
    44px;
}

.navigator-collapsed.inspector-collapsed .workbench-body {
  grid-template-columns:
    52px
    minmax(0, 1fr)
    44px;
}

/* ============================================================
   SIDE PANELS
   ============================================================ */

.navigator,
.inspector {
  min-height: 0;
  overflow: auto;
  background: var(--surface);
}

.navigator {
  border-right: 1px solid var(--border);
  padding: 16px 10px;
}

.inspector {
  border-left: 1px solid var(--border);
  padding: 18px 14px;
}

.navigator-collapsed .navigator {
  padding-inline: 8px;
}

.inspector-collapsed .inspector {
  padding-inline: 8px;
}

.side-panel-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 32px;
  margin: -8px -4px 12px;
  padding: 0 5px 0 8px;
  color: var(--faint);
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.navigator-collapsed .side-panel-toolbar,
.inspector-collapsed .side-panel-toolbar {
  justify-content: center;
  padding: 0;
}

.side-panel-toggle {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--faint);
  cursor: pointer;
}

.side-panel-toggle:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

/* ============================================================
   NAVIGATION
   ============================================================ */

.navigator-section + .navigator-section {
  margin-top: 28px;
}

.navigator-collapsed .navigator-section + .navigator-section {
  margin-top: 12px;
}

.section-label,
.card-label,
.eyebrow {
  margin: 0;
  color: var(--faint);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.section-label {
  padding: 0 8px;
}

.primary-navigation,
.context-navigation {
  display: grid;
  gap: 2px;
  margin-top: 8px;
}

.nav-item,
.context-item {
  display: flex;
  gap: 9px;
  align-items: center;
  width: 100%;
  border: 0;
  border-radius: 6px;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.nav-item {
  height: 34px;
  padding: 0 9px;
  color: var(--muted);
}

.context-item {
  height: 30px;
  padding: 0 9px;
  color: var(--muted);
  font-size: 12px;
}

.nav-item:hover,
.context-item:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.nav-item.active {
  background: var(--accent-muted);
  color: var(--foreground);
}

.navigation-icon {
  flex: 0 0 auto;
}

.navigator-collapsed .nav-item,
.navigator-collapsed .context-item {
  justify-content: center;
  padding: 0;
}

.collapsed-group-divider {
  height: 1px;
  margin: 8px 7px;
  background: var(--border-subtle);
}

/* ============================================================
   MAIN WORKSPACE
   ============================================================ */

.workspace {
  min-width: 0;
  overflow: auto;
  padding: 34px 38px 60px;
}

.workspace-header {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: flex-start;
  max-width: 1180px;
  margin: 0 auto 28px;
}

.workspace-header h1 {
  margin: 6px 0 7px;
  font-size: 25px;
  font-weight: 620;
  letter-spacing: -0.025em;
}

.workspace-description {
  max-width: 680px;
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.branch-chip {
  display: flex;
  gap: 7px;
  align-items: center;
  flex: 0 0 auto;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface);
  padding: 7px 10px;
  color: var(--muted);
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  font-size: 11px;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}

/* ============================================================
   SUMMARY CARDS
   ============================================================ */

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  max-width: 1180px;
  margin: 0 auto 10px;
}

.summary-card,
.panel {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
}

.summary-card {
  min-height: 132px;
  padding: 16px;
}

.summary-card strong {
  display: block;
  margin-top: 14px;
  font-size: 21px;
  font-weight: 590;
  letter-spacing: -0.02em;
}

.summary-card p:last-child {
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

/* ============================================================
   PANELS
   ============================================================ */

.workspace-columns {
  display: grid;
  grid-template-columns:
    minmax(0, 1.1fr)
    minmax(340px, 0.9fr);
  gap: 10px;
  max-width: 1180px;
  margin: 0 auto;
}

.panel {
  overflow: hidden;
}

.panel-heading {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  min-height: 67px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 13px 16px;
}

.panel-heading .section-label {
  padding: 0;
}

.panel-heading h2,
.next-panel h2 {
  margin: 4px 0 0;
  font-size: 14px;
  font-weight: 570;
}

.count-badge {
  display: grid;
  place-items: center;
  min-width: 25px;
  height: 21px;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 0 7px;
  color: var(--muted);
  font-size: 10px;
}

.empty-state,
.remaining-changes {
  padding: 18px 16px;
  color: var(--muted);
  font-size: 12px;
}

.empty-state p {
  margin: 0;
}

.remaining-changes {
  margin: 0;
}

/* ============================================================
   CURRENT PRODUCT / EXECUTION CONTEXT
   ============================================================ */

.context-stack {
  display: grid;
}

.context-object {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  min-height: 62px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 11px 16px;
}

.context-object > div {
  display: grid;
  gap: 5px;
}

.context-object code {
  color: var(--accent);
  font-size: 10px;
}

.context-object strong {
  font-size: 12px;
  font-weight: 540;
}

.context-object-link {
  color: inherit;
  text-decoration: none;
}

.context-object-link:hover {
  background: var(--surface-hover);
}

.muted-object {
  color: var(--faint);
}

.lifecycle-badge {
  flex: 0 0 auto;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 4px 7px;
  color: var(--muted);
  font-size: 9px;
}

.story-section,
.authority-note {
  padding: 16px;
}

.story-section .section-label,
.authority-note .section-label {
  padding: 0;
}

.story-list {
  display: grid;
  gap: 7px;
  margin-top: 12px;
}

.story-row {
  display: grid;
  grid-template-columns: 62px 1fr;
  gap: 10px;
  color: var(--muted);
  font-size: 11px;
}

.story-row code {
  color: var(--foreground);
  font-size: 10px;
}

.story-row-link {
  border-radius: 5px;
  margin-inline: -6px;
  padding: 5px 6px;
  color: var(--muted);
  text-decoration: none;
}

.story-row-link:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.authority-note code {
  display: block;
  margin-top: 10px;
  color: var(--muted);
  font-size: 10px;
}

/* ============================================================
   REPOSITORY STATE
   ============================================================ */

.secondary-columns {
  margin-top: 10px;
}

.compact-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

.compact-metrics > div {
  display: grid;
  gap: 7px;
  border-right: 1px solid var(--border-subtle);
  padding: 16px;
}

.compact-metrics > div:last-child {
  border-right: 0;
}

.compact-metrics span {
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
}

.compact-metrics code,
.compact-metrics strong {
  overflow: hidden;
  font-size: 11px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.repository-panel {
  max-width: 1180px;
  margin: 10px auto 0;
}

/* ============================================================
   KNOWLEDGE PROJECTION
   ============================================================ */

.knowledge-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  max-width: 1180px;
  margin: 10px auto 0;
}

.knowledge-reference-list,
.acceptance-list {
  display: grid;
}

.knowledge-reference {
  display: grid;
  grid-template-columns:
    minmax(120px, auto)
    auto;
  gap: 6px 16px;
  align-items: center;
  min-height: 52px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 9px 16px;
}

.knowledge-reference:last-child {
  border-bottom: 0;
}

.knowledge-reference > div {
  display: flex;
  gap: 8px;
  align-items: center;
}

.knowledge-reference > div code {
  color: var(--foreground);
  font-size: 10px;
}

.knowledge-reference > div span {
  color: var(--faint);
  font-size: 9px;
}

.knowledge-reference-link {
  color: inherit;
  text-decoration: none;
}

.knowledge-reference-link:hover {
  background: var(--surface-hover);
}

.relationship-label {
  justify-self: end;
  color: var(--muted);
  font-size: 9px;
  text-transform: uppercase;
}

.knowledge-path {
  grid-column: 1 / -1;
  overflow: hidden;
  color: var(--faint);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.acceptance-row {
  display: grid;
  grid-template-columns: 20px 1fr;
  gap: 8px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 11px 16px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.acceptance-row:last-child {
  border-bottom: 0;
}

.criterion-state {
  color: var(--faint);
}

.criterion-state.complete {
  color: var(--accent);
}

.execution-summary {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  border-bottom: 1px solid var(--border-subtle);
}

.execution-summary > div {
  display: grid;
  gap: 6px;
  padding: 15px 16px;
}

.execution-summary > div:first-child {
  border-right: 1px solid var(--border-subtle);
}

.execution-summary span {
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
}

.execution-summary strong {
  font-size: 17px;
  font-weight: 550;
}

.knowledge-empty {
  display: grid;
  gap: 5px;
}

.knowledge-empty span {
  color: var(--faint);
  line-height: 1.5;
}

.execution-record {
  display: grid;
  grid-template-columns:
    90px
    1fr
    1fr;
  gap: 10px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 10px 16px;
  color: var(--muted);
  font-size: 10px;
}

.execution-record code {
  color: var(--foreground);
}

/* ============================================================
   INSPECTOR
   ============================================================ */

.inspector-heading {
  padding: 0 6px 17px;
  border-bottom: 1px solid var(--border-subtle);
}

.inspector-heading .section-label {
  padding: 0;
}

.inspector-heading h2 {
  margin: 14px 0 2px;
  font-size: 16px;
  font-weight: 590;
}

.inspector-heading > p:last-child {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.metadata-list {
  margin: 0;
}

.metadata-list > div {
  display: grid;
  grid-template-columns: 92px 1fr;
  gap: 10px;
  padding: 12px 6px;
  border-bottom: 1px solid var(--border-subtle);
}

.metadata-list dt {
  color: var(--faint);
  font-size: 10px;
}

.metadata-list dd {
  min-width: 0;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.metadata-list code {
  color: var(--foreground);
  font-size: 10px;
}

.inspector-section {
  margin-top: 22px;
}

.inspector-section .section-label {
  padding: 0 6px;
}

.source-path {
  display: block;
  overflow-wrap: anywhere;
  margin-top: 9px;
  padding: 0 6px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.6;
}

.focus-relations {
  display: grid;
  gap: 2px;
  margin-top: 9px;
}

.focus-relation {
  display: grid;
  gap: 5px;
  border-radius: 6px;
  padding: 8px 6px;
  color: var(--muted);
  text-decoration: none;
}

.focus-relation:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.focus-relation > div {
  display: flex;
  gap: 7px;
  align-items: center;
}

.focus-relation > div > span {
  color: var(--faint);
  font-size: 9px;
}

.focus-relation code {
  color: var(--foreground);
  font-size: 10px;
}

.focus-relation > span {
  padding-left: 18px;
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
}

.relation-empty {
  margin: 0;
  padding: 7px 6px;
  color: var(--faint);
  font-size: 10px;
}

.return-to-current {
  display: block;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 9px 10px;
  color: var(--muted);
  font-size: 10px;
  text-decoration: none;
}

.return-to-current:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.open-focus {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 9px 10px;
  color: var(--foreground);
  font-size: 10px;
  text-decoration: none;
}

.open-focus:hover {
  border-color: var(--accent);
  background: var(--accent-muted);
}

.open-focus span {
  color: var(--accent);
}

/* ============================================================
   FOCUS WORKSPACE
   ============================================================ */

.focus-workspace {
  padding-bottom: 80px;
}

.focus-header {
  display: flex;
  justify-content: space-between;
  gap: 30px;
  align-items: flex-start;
  max-width: 1180px;
  margin: 0 auto 20px;
}

.focus-header h1 {
  max-width: 780px;
  margin: 8px 0 0;
  font-size: 27px;
  font-weight: 620;
  letter-spacing: -0.025em;
}

.focus-title-row {
  display: flex;
  gap: 9px;
  align-items: center;
  margin-top: 8px;
}

.focus-title-row > code {
  color: var(--accent);
  font-size: 11px;
}

.back-to-now {
  flex: 0 0 auto;
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 8px 10px;
  color: var(--muted);
  font-size: 10px;
  text-decoration: none;
}

.back-to-now:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.focus-overview-grid,
.focus-relationship-grid {
  display: grid;
  grid-template-columns:
    minmax(0, 1.35fr)
    minmax(280px, 0.65fr);
  gap: 10px;
  max-width: 1180px;
  margin: 0 auto 10px;
}

.focus-relationship-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.focus-summary-panel {
  min-height: 190px;
}

.focus-copy {
  padding: 18px 20px 21px;
  color: var(--muted);
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  font-size: 12px;
  line-height: 1.7;
  white-space: pre-wrap;
}

.focus-metadata {
  margin: 0;
}

.focus-metadata > div {
  display: grid;
  grid-template-columns: 100px 1fr;
  gap: 12px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 11px 16px;
}

.focus-metadata > div:last-child {
  border-bottom: 0;
}

.focus-metadata dt {
  color: var(--faint);
  font-size: 9px;
}

.focus-metadata dd {
  overflow-wrap: anywhere;
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}

.focus-metadata code {
  color: var(--foreground);
  font-size: 10px;
}

.focus-workspace-relations {
  display: grid;
}

.focus-workspace-relation {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  min-height: 50px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 9px 16px;
  color: inherit;
  text-decoration: none;
}

.focus-workspace-relation:last-child {
  border-bottom: 0;
}

.focus-workspace-relation:hover {
  background: var(--surface-hover);
}

.focus-workspace-relation > div {
  display: grid;
  gap: 4px;
}

.focus-workspace-relation code {
  color: var(--foreground);
  font-size: 10px;
}

.focus-workspace-relation div > span {
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
}

.focus-workspace-relation > span {
  color: var(--faint);
}

.focus-document-block,
.focus-source-panel {
  max-width: 1180px;
  margin: 10px auto 0;
}

.focus-source {
  padding: 17px 20px;
}

.focus-source code {
  color: var(--muted);
  font-size: 10px;
}

/* ============================================================
   CONTEXT MENU
   ============================================================ */

.context-menu {
  position: fixed;
  z-index: 1000;
  display: grid;
  width: 230px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface-raised);
  padding: 5px;
  box-shadow:
    0 18px 48px rgb(0 0 0 / 45%),
    0 4px 12px rgb(0 0 0 / 30%);
  user-select: none;
}

.context-menu button {
  display: flex;
  gap: 9px;
  align-items: center;
  height: 31px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  padding: 0 9px;
  color: var(--muted);
  text-align: left;
  font-size: 11px;
  cursor: default;
}

.context-menu button:hover:not(:disabled) {
  background: var(--surface-hover);
  color: var(--foreground);
}

.context-menu button:disabled {
  color: var(--faint);
  opacity: 0.55;
}

.context-menu-separator {
  height: 1px;
  margin: 4px 5px;
  background: var(--border);
}

/* ============================================================
   STATUS BAR
   ============================================================ */

.statusbar {
  display: flex;
  gap: 20px;
  align-items: center;
  border-top: 1px solid var(--border);
  background: var(--surface);
  padding: 0 10px;
  color: var(--faint);
  font-size: 10px;
}

.statusbar span:first-child {
  margin-right: auto;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1250px) {
  .workbench-body {
    grid-template-columns:
      210px
      minmax(0, 1fr)
      250px;
  }

  .navigator-collapsed .workbench-body {
    grid-template-columns:
      52px
      minmax(0, 1fr)
      250px;
  }

  .inspector-collapsed .workbench-body {
    grid-template-columns:
      210px
      minmax(0, 1fr)
      44px;
  }

  .navigator-collapsed.inspector-collapsed .workbench-body {
    grid-template-columns:
      52px
      minmax(0, 1fr)
      44px;
  }

  .topbar {
    grid-template-columns:
      210px
      minmax(0, 1fr)
      auto;
  }

  .navigator-collapsed .topbar {
    grid-template-columns:
      52px
      minmax(0, 1fr)
      auto;
  }

  .workspace {
    padding-inline: 24px;
  }

  .summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .knowledge-grid,
  .focus-overview-grid,
  .focus-relationship-grid {
    grid-template-columns: 1fr;
  }
}

sections.text:
:root {
  --background: #0d0f12;
  --surface: #12151a;
  --surface-raised: #171b21;
  --surface-hover: #1d222a;
  --border: #272d36;
  --border-subtle: #1e232b;
  --foreground: #ecedf0;
  --muted: #9299a5;
  --faint: #656d79;
  --accent: #c5ff55;
  --accent-muted: rgb(197 255 85 / 9%);
  --danger: #ff7676;
  --radius: 10px;
}

* {
  box-sizing: border-box;
  scrollbar-width: thin;
  scrollbar-color: #3b424e transparent;
}

*::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

*::-webkit-scrollbar-track {
  background: transparent;
}

*::-webkit-scrollbar-thumb {
  min-height: 34px;
  border: 2px solid transparent;
  border-radius: 999px;
  background: #3b424e;
  background-clip: padding-box;
}

*::-webkit-scrollbar-thumb:hover {
  background: #555e6c;
  background-clip: padding-box;
}

*::-webkit-scrollbar-corner {
  background: transparent;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  font-size: 14px;
}

button,
input {
  font: inherit;
}

button {
  color: inherit;
}

code,
kbd {
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
}

/* ============================================================
   APPLICATION SHELL
   ============================================================ */

.workbench {
  display: grid;
  grid-template-rows:
    28px
    34px
    48px
    minmax(0, 1fr)
    26px;
  height: 100vh;
  min-width: 900px;
  overflow: hidden;
}

/* ============================================================
   APPLICATION MENU BAR
   ============================================================ */

.application-menu-bar {
  position: relative;
  z-index: 60;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border-subtle);
  background: #0b0d10;
  padding: 0 8px;
  user-select: none;
}

.application-menus {
  position: relative;
  display: flex;
  align-items: center;
  height: 100%;
}

.application-menu-button {
  height: 22px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  padding: 0 8px;
  color: var(--muted);
  font-size: 11px;
  cursor: default;
}

.application-menu-button:hover,
.application-menu-button.active {
  background: var(--surface-hover);
  color: var(--foreground);
}

.application-title {
  padding-right: 5px;
  color: var(--faint);
  font-size: 10px;
}

.application-menu-dropdown {
  position: absolute;
  top: 27px;
  left: 0;
  z-index: 100;
  display: grid;
  min-width: 190px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface-raised);
  padding: 5px;
  box-shadow:
    0 12px 34px rgb(0 0 0 / 35%),
    0 2px 8px rgb(0 0 0 / 30%);
}

.application-menu-dropdown button {
  height: 30px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  padding: 0 9px;
  color: var(--muted);
  text-align: left;
  font-size: 11px;
  cursor: default;
}

.application-menu-dropdown button:hover:not(:disabled) {
  background: var(--surface-hover);
  color: var(--foreground);
}

.application-menu-dropdown button:disabled {
  color: var(--faint);
}

/* ============================================================
   TAB BAR
   ============================================================ */

.tab-bar {
  display: flex;
  align-items: stretch;
  border-bottom: 1px solid var(--border);
  background: #0e1115;
  user-select: none;
}

.tabs {
  display: flex;
  min-width: 0;
}

.workbench-tab {
  display: flex;
  gap: 7px;
  align-items: center;
  min-width: 130px;
  max-width: 220px;
  height: 100%;
  border: 0;
  border-right: 1px solid var(--border);
  background: transparent;
  padding: 0 12px;
  color: var(--muted);
  font-size: 10px;
  cursor: default;
}

.workbench-tab span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.workbench-tab.active {
  position: relative;
  background: var(--surface);
  color: var(--foreground);
}

.workbench-tab.active::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 1px;
  background: var(--surface);
  content: "";
}

.new-tab-button {
  width: 34px;
  border: 0;
  border-right: 1px solid var(--border);
  background: transparent;
  color: var(--faint);
  cursor: default;
}

.new-tab-button:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

/* ============================================================
   CONTEXT / BREADCRUMB BAR
   ============================================================ */

.topbar {
  display: grid;
  grid-template-columns:
    240px
    minmax(0, 1fr)
    auto;
  align-items: center;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  padding-right: 12px;
}

.navigator-collapsed .topbar {
  grid-template-columns:
    52px
    minmax(0, 1fr)
    auto;
}

.brand {
  display: flex;
  gap: 10px;
  align-items: center;
  height: 100%;
  padding: 0 14px;
  border-right: 1px solid var(--border);
}

.navigator-collapsed .brand {
  justify-content: center;
  padding: 0;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface-raised);
  color: var(--accent);
  font-weight: 700;
}

.brand-text {
  display: flex;
  gap: 6px;
  align-items: baseline;
}

.navigator-collapsed .brand-text {
  display: none;
}

.brand-text strong {
  font-size: 14px;
}

.brand-text span {
  color: var(--muted);
  font-size: 12px;
}

.topbar-context {
  display: flex;
  gap: 7px;
  align-items: center;
  min-width: 0;
  padding: 0 18px;
  color: var(--muted);
  font-size: 12px;
}

.topbar-context strong {
  overflow: hidden;
  color: var(--foreground);
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-separator {
  color: var(--faint);
}

.command-button {
  display: flex;
  gap: 22px;
  align-items: center;
  height: 32px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface-raised);
  padding: 0 8px 0 11px;
  color: var(--muted);
  cursor: pointer;
}

.command-button:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.command-button kbd {
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--surface);
  padding: 2px 5px;
  color: var(--faint);
  font-size: 10px;
}

/* ============================================================
   MAIN WORKBENCH GRID
   ============================================================ */

.workbench-body {
  display: grid;
  grid-template-columns:
    240px
    minmax(0, 1fr)
    280px;
  min-height: 0;
}

.navigator-collapsed .workbench-body {
  grid-template-columns:
    52px
    minmax(0, 1fr)
    280px;
}

.inspector-collapsed .workbench-body {
  grid-template-columns:
    240px
    minmax(0, 1fr)
    44px;
}

.navigator-collapsed.inspector-collapsed .workbench-body {
  grid-template-columns:
    52px
    minmax(0, 1fr)
    44px;
}

/* ============================================================
   SIDE PANELS
   ============================================================ */

.navigator,
.inspector {
  min-height: 0;
  overflow: auto;
  background: var(--surface);
}

.navigator {
  border-right: 1px solid var(--border);
  padding: 16px 10px;
}

.inspector {
  border-left: 1px solid var(--border);
  padding: 18px 14px;
}

.navigator-collapsed .navigator {
  padding-inline: 8px;
}

.inspector-collapsed .inspector {
  padding-inline: 8px;
}

.side-panel-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 32px;
  margin: -8px -4px 12px;
  padding: 0 5px 0 8px;
  color: var(--faint);
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.navigator-collapsed .side-panel-toolbar,
.inspector-collapsed .side-panel-toolbar {
  justify-content: center;
  padding: 0;
}

.side-panel-toggle {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--faint);
  cursor: pointer;
}

.side-panel-toggle:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

/* ============================================================
   NAVIGATION
   ============================================================ */

.navigator-section + .navigator-section {
  margin-top: 28px;
}

.navigator-collapsed .navigator-section + .navigator-section {
  margin-top: 12px;
}

.section-label,
.card-label,
.eyebrow {
  margin: 0;
  color: var(--faint);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.section-label {
  padding: 0 8px;
}

.primary-navigation,
.context-navigation {
  display: grid;
  gap: 2px;
  margin-top: 8px;
}

.nav-item,
.context-item {
  display: flex;
  gap: 9px;
  align-items: center;
  width: 100%;
  border: 0;
  border-radius: 6px;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.nav-item {
  height: 34px;
  padding: 0 9px;
  color: var(--muted);
}

.context-item {
  height: 30px;
  padding: 0 9px;
  color: var(--muted);
  font-size: 12px;
}

.nav-item:hover,
.context-item:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.nav-item.active {
  background: var(--accent-muted);
  color: var(--foreground);
}

.navigation-icon {
  flex: 0 0 auto;
}

.navigator-collapsed .nav-item,
.navigator-collapsed .context-item {
  justify-content: center;
  padding: 0;
}

.collapsed-group-divider {
  height: 1px;
  margin: 8px 7px;
  background: var(--border-subtle);
}

/* ============================================================
   MAIN WORKSPACE
   ============================================================ */

.workspace {
  min-width: 0;
  overflow: auto;
  padding: 34px 38px 60px;
}

.workspace-header {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: flex-start;
  max-width: 1180px;
  margin: 0 auto 28px;
}

.workspace-header h1 {
  margin: 6px 0 7px;
  font-size: 25px;
  font-weight: 620;
  letter-spacing: -0.025em;
}

.workspace-description {
  max-width: 680px;
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
}

.branch-chip {
  display: flex;
  gap: 7px;
  align-items: center;
  flex: 0 0 auto;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface);
  padding: 7px 10px;
  color: var(--muted);
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  font-size: 11px;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}

/* ============================================================
   SUMMARY CARDS
   ============================================================ */

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  max-width: 1180px;
  margin: 0 auto 10px;
}

.summary-card,
.panel {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
}

.summary-card {
  min-height: 132px;
  padding: 16px;
}

.summary-card strong {
  display: block;
  margin-top: 14px;
  font-size: 21px;
  font-weight: 590;
  letter-spacing: -0.02em;
}

.summary-card p:last-child {
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

/* ============================================================
   PANELS
   ============================================================ */

.workspace-columns {
  display: grid;
  grid-template-columns:
    minmax(0, 1.1fr)
    minmax(340px, 0.9fr);
  gap: 10px;
  max-width: 1180px;
  margin: 0 auto;
}

.panel {
  overflow: hidden;
}

.panel-heading {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  min-height: 67px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 13px 16px;
}

.panel-heading .section-label {
  padding: 0;
}

.panel-heading h2,
.next-panel h2 {
  margin: 4px 0 0;
  font-size: 14px;
  font-weight: 570;
}

.count-badge {
  display: grid;
  place-items: center;
  min-width: 25px;
  height: 21px;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 0 7px;
  color: var(--muted);
  font-size: 10px;
}

.empty-state,
.remaining-changes {
  padding: 18px 16px;
  color: var(--muted);
  font-size: 12px;
}

.empty-state p {
  margin: 0;
}

.remaining-changes {
  margin: 0;
}

/* ============================================================
   CURRENT PRODUCT / EXECUTION CONTEXT
   ============================================================ */

.context-stack {
  display: grid;
}

.context-object {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  min-height: 62px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 11px 16px;
}

.context-object > div {
  display: grid;
  gap: 5px;
}

.context-object code {
  color: var(--accent);
  font-size: 10px;
}

.context-object strong {
  font-size: 12px;
  font-weight: 540;
}

.context-object-link {
  color: inherit;
  text-decoration: none;
}

.context-object-link:hover {
  background: var(--surface-hover);
}

.muted-object {
  color: var(--faint);
}

.lifecycle-badge {
  flex: 0 0 auto;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 4px 7px;
  color: var(--muted);
  font-size: 9px;
}

.story-section,
.authority-note {
  padding: 16px;
}

.story-section .section-label,
.authority-note .section-label {
  padding: 0;
}

.story-list {
  display: grid;
  gap: 7px;
  margin-top: 12px;
}

.story-row {
  display: grid;
  grid-template-columns: 62px 1fr;
  gap: 10px;
  color: var(--muted);
  font-size: 11px;
}

.story-row code {
  color: var(--foreground);
  font-size: 10px;
}

.story-row-link {
  border-radius: 5px;
  margin-inline: -6px;
  padding: 5px 6px;
  color: var(--muted);
  text-decoration: none;
}

.story-row-link:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.authority-note code {
  display: block;
  margin-top: 10px;
  color: var(--muted);
  font-size: 10px;
}

/* ============================================================
   REPOSITORY STATE
   ============================================================ */

.secondary-columns {
  margin-top: 10px;
}

.compact-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

.compact-metrics > div {
  display: grid;
  gap: 7px;
  border-right: 1px solid var(--border-subtle);
  padding: 16px;
}

.compact-metrics > div:last-child {
  border-right: 0;
}

.compact-metrics span {
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
}

.compact-metrics code,
.compact-metrics strong {
  overflow: hidden;
  font-size: 11px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.repository-panel {
  max-width: 1180px;
  margin: 10px auto 0;
}

/* ============================================================
   KNOWLEDGE PROJECTION
   ============================================================ */

.knowledge-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  max-width: 1180px;
  margin: 10px auto 0;
}

.knowledge-reference-list,
.acceptance-list {
  display: grid;
}

.knowledge-reference {
  display: grid;
  grid-template-columns:
    minmax(120px, auto)
    auto;
  gap: 6px 16px;
  align-items: center;
  min-height: 52px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 9px 16px;
}

.knowledge-reference:last-child {
  border-bottom: 0;
}

.knowledge-reference > div {
  display: flex;
  gap: 8px;
  align-items: center;
}

.knowledge-reference > div code {
  color: var(--foreground);
  font-size: 10px;
}

.knowledge-reference > div span {
  color: var(--faint);
  font-size: 9px;
}

.knowledge-reference-link {
  color: inherit;
  text-decoration: none;
}

.knowledge-reference-link:hover {
  background: var(--surface-hover);
}

.relationship-label {
  justify-self: end;
  color: var(--muted);
  font-size: 9px;
  text-transform: uppercase;
}

.knowledge-path {
  grid-column: 1 / -1;
  overflow: hidden;
  color: var(--faint);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.acceptance-row {
  display: grid;
  grid-template-columns: 20px 1fr;
  gap: 8px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 11px 16px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.acceptance-row:last-child {
  border-bottom: 0;
}

.criterion-state {
  color: var(--faint);
}

.criterion-state.complete {
  color: var(--accent);
}

.execution-summary {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  border-bottom: 1px solid var(--border-subtle);
}

.execution-summary > div {
  display: grid;
  gap: 6px;
  padding: 15px 16px;
}

.execution-summary > div:first-child {
  border-right: 1px solid var(--border-subtle);
}

.execution-summary span {
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
}

.execution-summary strong {
  font-size: 17px;
  font-weight: 550;
}

.knowledge-empty {
  display: grid;
  gap: 5px;
}

.knowledge-empty span {
  color: var(--faint);
  line-height: 1.5;
}

.execution-record {
  display: grid;
  grid-template-columns:
    90px
    1fr
    1fr;
  gap: 10px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 10px 16px;
  color: var(--muted);
  font-size: 10px;
}

.execution-record code {
  color: var(--foreground);
}

/* ============================================================
   INSPECTOR
   ============================================================ */

.inspector-heading {
  padding: 0 6px 17px;
  border-bottom: 1px solid var(--border-subtle);
}

.inspector-heading .section-label {
  padding: 0;
}

.inspector-heading h2 {
  margin: 14px 0 2px;
  font-size: 16px;
  font-weight: 590;
}

.inspector-heading > p:last-child {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.metadata-list {
  margin: 0;
}

.metadata-list > div {
  display: grid;
  grid-template-columns: 92px 1fr;
  gap: 10px;
  padding: 12px 6px;
  border-bottom: 1px solid var(--border-subtle);
}

.metadata-list dt {
  color: var(--faint);
  font-size: 10px;
}

.metadata-list dd {
  min-width: 0;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.metadata-list code {
  color: var(--foreground);
  font-size: 10px;
}

.inspector-section {
  margin-top: 22px;
}

.inspector-section .section-label {
  padding: 0 6px;
}

.source-path {
  display: block;
  overflow-wrap: anywhere;
  margin-top: 9px;
  padding: 0 6px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.6;
}

.focus-relations {
  display: grid;
  gap: 2px;
  margin-top: 9px;
}

.focus-relation {
  display: grid;
  gap: 5px;
  border-radius: 6px;
  padding: 8px 6px;
  color: var(--muted);
  text-decoration: none;
}

.focus-relation:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.focus-relation > div {
  display: flex;
  gap: 7px;
  align-items: center;
}

.focus-relation > div > span {
  color: var(--faint);
  font-size: 9px;
}

.focus-relation code {
  color: var(--foreground);
  font-size: 10px;
}

.focus-relation > span {
  padding-left: 18px;
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
}

.relation-empty {
  margin: 0;
  padding: 7px 6px;
  color: var(--faint);
  font-size: 10px;
}

.return-to-current {
  display: block;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 9px 10px;
  color: var(--muted);
  font-size: 10px;
  text-decoration: none;
}

.return-to-current:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.open-focus {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 9px 10px;
  color: var(--foreground);
  font-size: 10px;
  text-decoration: none;
}

.open-focus:hover {
  border-color: var(--accent);
  background: var(--accent-muted);
}

.open-focus span {
  color: var(--accent);
}

/* ============================================================
   FOCUS WORKSPACE
   ============================================================ */

.focus-workspace {
  padding-bottom: 80px;
}

.focus-header {
  display: flex;
  justify-content: space-between;
  gap: 30px;
  align-items: flex-start;
  max-width: 1180px;
  margin: 0 auto 20px;
}

.focus-header h1 {
  max-width: 780px;
  margin: 8px 0 0;
  font-size: 27px;
  font-weight: 620;
  letter-spacing: -0.025em;
}

.focus-title-row {
  display: flex;
  gap: 9px;
  align-items: center;
  margin-top: 8px;
}

.focus-title-row > code {
  color: var(--accent);
  font-size: 11px;
}

.back-to-now {
  flex: 0 0 auto;
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 8px 10px;
  color: var(--muted);
  font-size: 10px;
  text-decoration: none;
}

.back-to-now:hover {
  background: var(--surface-hover);
  color: var(--foreground);
}

.focus-overview-grid,
.focus-relationship-grid {
  display: grid;
  grid-template-columns:
    minmax(0, 1.35fr)
    minmax(280px, 0.65fr);
  gap: 10px;
  max-width: 1180px;
  margin: 0 auto 10px;
}

.focus-relationship-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.focus-summary-panel {
  min-height: 190px;
}

.focus-copy {
  padding: 18px 20px 21px;
  color: var(--muted);
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  font-size: 12px;
  line-height: 1.7;
  white-space: pre-wrap;
}

.focus-metadata {
  margin: 0;
}

.focus-metadata > div {
  display: grid;
  grid-template-columns: 100px 1fr;
  gap: 12px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 11px 16px;
}

.focus-metadata > div:last-child {
  border-bottom: 0;
}

.focus-metadata dt {
  color: var(--faint);
  font-size: 9px;
}

.focus-metadata dd {
  overflow-wrap: anywhere;
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}

.focus-metadata code {
  color: var(--foreground);
  font-size: 10px;
}

.focus-workspace-relations {
  display: grid;
}

.focus-workspace-relation {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  min-height: 50px;
  border-bottom: 1px solid var(--border-subtle);
  padding: 9px 16px;
  color: inherit;
  text-decoration: none;
}

.focus-workspace-relation:last-child {
  border-bottom: 0;
}

.focus-workspace-relation:hover {
  background: var(--surface-hover);
}

.focus-workspace-relation > div {
  display: grid;
  gap: 4px;
}

.focus-workspace-relation code {
  color: var(--foreground);
  font-size: 10px;
}

.focus-workspace-relation div > span {
  color: var(--faint);
  font-size: 9px;
  text-transform: uppercase;
}

.focus-workspace-relation > span {
  color: var(--faint);
}

.focus-document-block,
.focus-source-panel {
  max-width: 1180px;
  margin: 10px auto 0;
}

.focus-source {
  padding: 17px 20px;
}

.focus-source code {
  color: var(--muted);
  font-size: 10px;
}

/* ============================================================
   CONTEXT MENU
   ============================================================ */

.context-menu {
  position: fixed;
  z-index: 1000;
  display: grid;
  width: 230px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface-raised);
  padding: 5px;
  box-shadow:
    0 18px 48px rgb(0 0 0 / 45%),
    0 4px 12px rgb(0 0 0 / 30%);
  user-select: none;
}

.context-menu button {
  display: flex;
  gap: 9px;
  align-items: center;
  height: 31px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  padding: 0 9px;
  color: var(--muted);
  text-align: left;
  font-size: 11px;
  cursor: default;
}

.context-menu button:hover:not(:disabled) {
  background: var(--surface-hover);
  color: var(--foreground);
}

.context-menu button:disabled {
  color: var(--faint);
  opacity: 0.55;
}

.context-menu-separator {
  height: 1px;
  margin: 4px 5px;
  background: var(--border);
}

/* ============================================================
   STATUS BAR
   ============================================================ */

.statusbar {
  display: flex;
  gap: 20px;
  align-items: center;
  border-top: 1px solid var(--border);
  background: var(--surface);
  padding: 0 10px;
  color: var(--faint);
  font-size: 10px;
}

.statusbar span:first-child {
  margin-right: auto;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1250px) {
  .workbench-body {
    grid-template-columns:
      210px
      minmax(0, 1fr)
      250px;
  }

  .navigator-collapsed .workbench-body {
    grid-template-columns:
      52px
      minmax(0, 1fr)
      250px;
  }

  .inspector-collapsed .workbench-body {
    grid-template-columns:
      210px
      minmax(0, 1fr)
      44px;
  }

  .navigator-collapsed.inspector-collapsed .workbench-body {
    grid-template-columns:
      52px
      minmax(0, 1fr)
      44px;
  }

  .topbar {
    grid-template-columns:
      210px
      minmax(0, 1fr)
      auto;
  }

  .navigator-collapsed .topbar {
    grid-template-columns:
      52px
      minmax(0, 1fr)
      auto;
  }

  .workspace {
    padding-inline: 24px;
  }

  .summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .knowledge-grid,
  .focus-overview-grid,
  .focus-relationship-grid {
    grid-template-columns: 1fr;
  }
}
